"""Native settings acceptance; run only inside the dedicated disposable QEMU guest."""
import os
from pathlib import Path
import subprocess
from protocol import Operation

assert subprocess.check_output(['systemd-detect-virt', '--vm']).strip() == b'qemu'
for setting, value, query in [
    ('hostname', 'vigil-settings-fixture', ['hostnamectl', '--static']),
    ('timezone', 'Asia/Shanghai', ['timedatectl', 'show', '--property=Timezone', '--value']),
    ('locale', 'C.UTF-8', ['localectl', 'status']),
]:
    operation = {'kind': 'system_settings_update', 'setting': setting, 'value': value}
    Operation(operation).finish()
    actual = subprocess.check_output(query, text=True)
    assert value in actual, (setting, actual)

path = Path('/etc/resolv.conf')
if path.is_symlink():
    path.unlink()
original = 'options timeout:2\nnameserver 8.8.8.8\n'
path.write_text(original)
configuration = {'servers': ['1.1.1.1', '2606:4700:4700::1111'], 'searchDomains': ['example.test']}
def dns(expected=None, success=True):
    return Operation({'kind': 'dns_update', 'configuration': configuration,
                      'expected_hash': expected}).finish(success)
preview = dns().result()
assert path.read_text() == original
dns('0' * 64, False)
assert path.read_text() == original
result = dns(preview['hash']).result()
assert result['changed'] and Path(result['backup']).read_text() == original
assert path.read_text() == 'options timeout:2\nnameserver 1.1.1.1\nnameserver 2606:4700:4700::1111\nsearch example.test\n'
path.write_text('# Generated by NetworkManager\nnameserver 8.8.8.8\n')
dns(success=False)
path.unlink()
target = Path('/tmp/vigil-resolver-fixture')
target.write_text(original)
path.symlink_to(target)
dns(success=False)
assert target.read_text() == original
print('PASS native hostname/timezone/locale readback; static DNS version/backup/options and managed/link refusal', flush=True)
